mapper.insert:
INSERT INTO material (
    id, owner_type, owner_key, kind, display_name, retention_class, origin_conversation_id,
    lifecycle_state, lifecycle_generation, latest_version_id, last_meaningful_activity_at,
    expires_at, trash_expires_at, deleted_at
) VALUES (
    #{id}, #{ownerType}, #{ownerKey}, #{kind}, #{displayName}, #{retentionClass},
    #{originConversationId}, #{lifecycleState}, #{lifecycleGeneration}, #{latestVersionId},
    #{lastMeaningfulActivityAt}, #{expiresAt}, #{trashExpiresAt}, #{deletedAt}
)

mapper.select:
SELECT *
FROM material
WHERE id = #{id}
  AND owner_type = #{ownerType}
  AND owner_key = #{ownerKey}

mapper.update:
UPDATE material
SET last_meaningful_activity_at = #{activityAt},
    expires_at = GREATEST(expires_at, #{expiresAt})
WHERE id = #{id}
  AND owner_type = #{ownerType}
  AND owner_key = #{ownerKey}
  AND retention_class = 'TEMPORARY'
  AND lifecycle_state = 'ACTIVE'
  AND lifecycle_generation = #{expectedGeneration}
  AND expires_at > UTC_TIMESTAMP(3)
